import string

def gen(rng):
    def fmt(ss):
        return str(len(ss)) + '\n' + '\n'.join(ss)
    def rs(L, alpha):
        return ''.join(rng.choice(alpha) for _ in range(L))
    V = 'aeiouAEIOU'
    L = string.ascii_letters
    tests = [fmt(['a']), fmt(['b']), fmt(['ae']), fmt(['abcde', 'acvbn', 'Etuilo']), fmt(['AbbA', 'Izzy', 'u', 'ok']), fmt(['aaaa', 'EEEEE', 'eIoUa'])]
    for _ in range(25):
        ss = []
        for _ in range(rng.randint(1, 8)):
            ln = rng.randint(1, 12)
            mode = rng.randint(0, 3)
            if mode == 0:
                s = rs(ln, L)
            elif mode == 1:
                s = rs(ln, V + 'bcd')
            elif mode == 2 and ln >= 2:
                s = rng.choice(V) + rs(ln - 2, L) + rng.choice(V)
            else:
                s = rs(ln, V)
            ss.append(s)
        tests.append(fmt(ss))
    tests.append(fmt([rng.choice(V) + rs(rng.randint(0, 50), L) + rng.choice(V) for _ in range(5)]))
    # max-size cases
    tests.append(fmt([rng.choice(V) + rs(8, L) + rng.choice(V) for _ in range(10**5)]))
    tests.append(fmt([rng.choice(V) + rs(998, L) + rng.choice(V) for _ in range(10**3)]))
    tests.append(fmt([rng.choice(V) + rs(10**6 - 2, L) + rng.choice(V)]))
    tests.append(fmt([rs(rng.randint(1, 19), V + 'xyz') for _ in range(10**5)]))
    return tests

